('Product Hunt', 'producthunt', 'https://www.producthunt.com', 'https://www.producthunt.com/posts/new', 1, ARRAY['Tech', 'SaaS', 'AI', 'Mobile', 'Developer Tools'], true, true, 91, 60, 260, 'Punchy, benefit-driven tagline, maker first comment explaining the backstory and problem solved. No cheesy marketing buzzwords.', true, 'verify: Check launch scheduling window (12:01 AM PST recommended) and Maker guidelines.', true),
('Hacker News (Show HN)', 'hackernews', 'https://news.ycombinator.com', 'https://news.ycombinator.com/submit', 1, ARRAY['Developer Tools', 'Open Source', 'Tech', 'AI', 'Infrastructure'], true, false, 92, 80, 2000, 'Plain text, hyper-technical, zero marketing fluff or hyperbole. Format title as ''Show HN: [Name] – [What it does in plain English]''. Explain architecture & motivation in first comment.', true, 'verify: Ensure account has minimal karma or age to avoid spam flag. Follow Show HN guidelines closely.', true),
('Reddit r/SideProject', 'reddit-sideproject', 'https://reddit.com/r/SideProject', 'https://reddit.com/r/SideProject/submit', 1, ARRAY['Side Projects', 'Indie Hacking', 'SaaS', 'Tools'], true, false, 90, 120, 1500, 'Humble, founder-led story. ''I built X to solve Y after struggling with Z''. Ask for honest feedback. Include a short video or demo link in the comments.', true, 'verify: Review subreddit self-promo rules (must be active participant).', true),
('Reddit r/SaaS', 'reddit-saas', 'https://reddit.com/r/SaaS', 'https://reddit.com/r/SaaS/submit', 1, ARRAY['SaaS', 'B2B', 'Indie Hacking', 'Startups'], true, false, 90, 120, 1500, 'Metrics, business learnings, problem discovery. Avoid pure advertisement; focus on lessons learned while building or customer validation stories.', true, 'verify: Check weekly self-promotion sticky threads or post rules.', true),
('Reddit r/indiehackers', 'reddit-indiehackers', 'https://reddit.com/r/indiehackers', 'https://reddit.com/r/indiehackers/submit', 1, ARRAY['Indie Hacking', 'Bootstrapping', 'Micro-SaaS'], true, false, 90, 120, 1500, 'Transparent building in public. Share revenue goals, tech stack decisions, and how you got your first users.', true, 'verify: Verify self-promo policy before posting direct links.', true),
('Indie Hackers', 'indiehackers', 'https://www.indiehackers.com', 'https://www.indiehackers.com/products/new', 1, ARRAY['Bootstrapping', 'Indie Hacking', 'SaaS', 'Community'], true, false, 84, 80, 1200, 'Transparent, founder journey, revenue milestones. Write a milestone post introducing the product and requesting feedback.', true, 'verify: Verify product page claim workflow.', true),

